package com.citacloud.springboot.contacloud.app.services;

import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.models.*;import com.citacloud.springboot.contacloud.app.repositories.*;import com.citacloud.springboot.contacloud.app.security.*;
import org.springframework.dao.DataIntegrityViolationException;import org.springframework.data.domain.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.math.*;import java.time.*;import java.util.*;

@Service
public class ValeCajaService {
 private static final UUID EMPTY_ID=new UUID(0L,0L);
 private static final Set<Integer> POS_SIZES=Set.of(5,10,20,50),ADMIN_SIZES=Set.of(10,20,50);
 private static final String CREATE="CASH_VOUCHER_CREATE",VOID="CASH_VOUCHER_VOID";
 private final ValeCajaRepository vales;private final ConceptoValeCajaRepository conceptos;private final CashRegisterSessionRepository sesiones;
 private final FinancialMovementRepository movimientos;private final IdempotentOperationService idempotencia;private final MovimientoCajaNumeroService numerosMovimiento;
 private final AuditoriaService auditoria;private final JdbcTemplate jdbc;
 private final CashRegisterRepository cajas;private final SucursalRepository sucursales;private final UsuarioRepository usuarios;private final EmpresaRepository empresas;
 private final DatosEmpresaRepository datosEmpresa;
 public ValeCajaService(ValeCajaRepository v,ConceptoValeCajaRepository c,CashRegisterSessionRepository s,FinancialMovementRepository m,
  IdempotentOperationService i,MovimientoCajaNumeroService n,AuditoriaService a,JdbcTemplate j,CashRegisterRepository cajas,
  SucursalRepository sucursales,UsuarioRepository usuarios,EmpresaRepository empresas,DatosEmpresaRepository datosEmpresa){vales=v;conceptos=c;sesiones=s;movimientos=m;idempotencia=i;numerosMovimiento=n;auditoria=a;jdbc=j;this.cajas=cajas;this.sucursales=sucursales;this.usuarios=usuarios;this.empresas=empresas;this.datosEmpresa=datosEmpresa;}

 @Transactional(readOnly=true) @PreAuthorize("@empresaModuloService.habilitado('CAJA_BANCOS') and hasAuthority('vales_caja.ver')")
 public RecuentoCajaCatalogosDto catalogos(){var p=TenantContext.principalActual();List<Sucursal> ramas=(p.accesoTodasSucursales()?sucursales.findAllByEmpresaIdOrderByNombre(p.empresaId()):sucursales.findAllByIdInAndEmpresaId(p.sucursalIds(),p.empresaId()).stream().sorted(Comparator.comparing(Sucursal::getNombre)).toList());Set<UUID> ids=ramas.stream().map(Sucursal::getId).collect(java.util.stream.Collectors.toSet());return new RecuentoCajaCatalogosDto(ramas.stream().map(x->new RecuentoCajaCatalogosDto.SucursalOpcion(x.getId(),x.getNombre())).toList(),cajas.findAllByTenantIdAndEmpresaIdOrderByNombre(p.tenantId(),p.empresaId()).stream().filter(x->ids.contains(x.getSucursalId())).map(x->new RecuentoCajaCatalogosDto.CajaOpcion(x.getId(),x.getSucursalId(),x.getNombre())).toList(),usuarios.findAllByTenantIdAndEmpresaIdOrderByNombreAscApellidoAsc(p.tenantId(),p.empresaId()).stream().map(x->new RecuentoCajaCatalogosDto.UsuarioOpcion(x.getId(),etiqueta(x))).toList());}

 @Transactional(readOnly=true) @PreAuthorize("@empresaModuloService.habilitado('CAJA_BANCOS') and hasAuthority('vales_caja.ver')")
 public ValeCajaContextoDto contexto(UUID sesionId){SesionCaja s=sesionPos(sesionId,false);var p=TenantContext.principalActual();return new ValeCajaContextoDto(s.getId(),s.getCaja().getNombre(),s.getSucursal().getNombre(),s.getMoneda().getCodigoIso(),s.getStatus()==EstadoSesionCaja.OPEN,
  conceptos.findAllByTenantIdAndEmpresaIdAndActiveTrueOrderByNameAsc(p.tenantId(),p.empresaId()).stream().map(this::map).toList());}

 @Transactional(readOnly=true) @PreAuthorize("@empresaModuloService.habilitado('CAJA_BANCOS') and hasAuthority('vales_caja.ver')")
 public Page<ValeCajaDto> buscarPos(UUID sesionId,String buscar,EstadoValeCaja estado,int pagina,int tamano){validarPagina(pagina,tamano,POS_SIZES);SesionCaja s=sesionPos(sesionId,false);var p=TenantContext.principalActual();return vales.buscarPos(p.tenantId(),p.empresaId(),s.getId(),limpiar(buscar),estado,PageRequest.of(pagina,tamano,Sort.by(Sort.Order.desc("fechaHora"),Sort.Order.desc("id")))).map(this::map);}

 @Transactional(readOnly=true) @PreAuthorize("@empresaModuloService.habilitado('CAJA_BANCOS') and hasAuthority('vales_caja.ver')")
 public Page<ValeCajaDto> buscarAdmin(String buscar,UUID sucursal,UUID caja,UUID usuario,EstadoValeCaja estado,LocalDate desde,LocalDate hasta,int pagina,int tamano){validarPagina(pagina,tamano,ADMIN_SIZES);if(desde!=null&&hasta!=null&&desde.isAfter(hasta))throw new ReglaNegocioException("La fecha desde no puede ser posterior a la fecha hasta.");var p=TenantContext.principalActual();if(sucursal!=null&&!EmpresaContext.permiteSucursal(sucursal))throw new RecursoNoEncontradoException("Sucursal no encontrada.");if(caja!=null)cajas.findByIdAndTenantIdAndEmpresaId(caja,p.tenantId(),p.empresaId()).filter(x->EmpresaContext.permiteSucursal(x.getSucursalId())&&(sucursal==null||sucursal.equals(x.getSucursalId()))).orElseThrow(()->new RecursoNoEncontradoException("Caja no encontrada."));if(usuario!=null)usuarios.findByIdAndTenantId(usuario,p.tenantId()).filter(x->p.empresaId().equals(x.getEmpresaId())).orElseThrow(()->new RecursoNoEncontradoException("Usuario no encontrado."));Set<UUID> permitidas=p.accesoTodasSucursales()?Set.of(EMPTY_ID):p.sucursalIds().isEmpty()?Set.of(EMPTY_ID):p.sucursalIds();ZoneId zona=zonaEmpresa(p.empresaId(),p.tenantId());OffsetDateTime inicio=desde==null?OffsetDateTime.ofInstant(Instant.EPOCH,ZoneOffset.UTC):desde.atStartOfDay(zona).toOffsetDateTime(),fin=hasta==null?OffsetDateTime.ofInstant(Instant.EPOCH,ZoneOffset.UTC):hasta.plusDays(1).atStartOfDay(zona).toOffsetDateTime();return vales.buscarAdmin(p.tenantId(),p.empresaId(),limpiar(buscar),sucursal!=null,valor(sucursal),caja!=null,valor(caja),usuario!=null,valor(usuario),estado!=null,estado==null?EstadoValeCaja.CONFIRMED:estado,desde!=null,inicio,hasta!=null,fin,p.accesoTodasSucursales(),permitidas,PageRequest.of(pagina,tamano,Sort.by(Sort.Order.desc("fechaHora"),Sort.Order.desc("id")))).map(this::map);}

 @Transactional(readOnly=true) @PreAuthorize("@empresaModuloService.habilitado('CAJA_BANCOS') and hasAuthority('vales_caja.ver')")
 public ValeCajaDto obtener(UUID id){return map(seguro(id));}

 @Transactional @PreAuthorize("@empresaModuloService.habilitado('CAJA_BANCOS') and hasAuthority('vales_caja.crear')")
 public ValeCajaDto confirmar(ValeCajaInput input){validar(input);var p=TenantContext.principalActual();String huella=CommandFingerprint.sha256(input);var op=idempotencia.begin(p.tenantId(),p.empresaId(),CREATE,input.idempotencia(),huella);if(op.replay())return map(seguro(op.resultId()));
  SesionCaja sesion=sesionBloqueada(input.sesionId());ConceptoValeCaja concepto=conceptos.findByIdAndTenantIdAndEmpresaIdAndActiveTrue(input.conceptoId(),p.tenantId(),p.empresaId()).orElseThrow(()->new ReglaNegocioException("El concepto seleccionado no está disponible."));
  String beneficiario=requerido(input.beneficiario(),180,"El beneficiario es obligatorio."),referencia=opcional(input.referencia(),100),observacion=opcional(input.observacion(),500);
  if(concepto.isRequiereReferencia()&&referencia==null)throw new ReglaNegocioException("La referencia es obligatoria para el concepto seleccionado.");if(concepto.isRequiereObservacion()&&observacion==null)throw new ReglaNegocioException("La observación es obligatoria para el concepto seleccionado.");
  Empresa empresa=empresas.findByIdAndTenantId(p.empresaId(),p.tenantId()).orElseThrow(()->new ReglaNegocioException("No fue posible identificar la empresa."));DatosEmpresa datos=datosEmpresa.findByEmpresaId(p.empresaId()).orElse(null);
  String numero=siguienteVale(p.tenantId(),p.empresaId());ValeCaja vale=new ValeCaja(p.tenantId(),p.empresaId(),sesion,concepto,numero,beneficiario,escala(input.importe()),referencia,observacion,p.usuarioId(),p.nombre(),input.idempotencia(),datos==null?empresa.getNombre():primero(datos.getNombreComercial(),empresa.getNombre()),empresa.getIdentificacionFiscal(),datos==null?null:datos.getDireccion(),datos==null?null:datos.getTelefono(),datos==null?null:datos.getCorreo(),empresa.getLogoObjectKey());
  try{vale=vales.saveAndFlush(vale);MovimientoFinanciero movimiento=MovimientoFinanciero.valeCaja(p.tenantId(),p.empresaId(),sesion.getFechaOperativa(),sesion.getCajaId(),sesion.getMonedaId(),vale.getImporte(),numerosMovimiento.siguiente(p.tenantId(),p.empresaId()),vale.getNumero(),vale.getConcepto(),vale.getBeneficiario(),vale.getObservacion(),vale.getId(),sesion.getId(),p.usuarioId());movimiento=movimientos.saveAndFlush(movimiento);vale.vincularMovimiento(movimiento.getId());vale=vales.saveAndFlush(vale);}catch(DataIntegrityViolationException ex){throw new ReglaNegocioException("El estado de la caja cambió. Actualice la información e intente nuevamente.",ex);}
  auditoria.registrar("CASH_VOUCHER_CONFIRMED","ValeCaja",vale.getId(),detalle(vale));idempotencia.complete(p.tenantId(),p.empresaId(),CREATE,input.idempotencia(),"CASH_VOUCHER",vale.getId());return map(vale);}

 @Transactional @PreAuthorize("@empresaModuloService.habilitado('CAJA_BANCOS') and hasAuthority('vales_caja.anular')")
 public ValeCajaDto anular(AnulacionValeCajaInput input){if(input==null||input.valeId()==null||input.idempotencia()==null)throw new ReglaNegocioException("No fue posible identificar el vale.");String motivo=requerido(input.motivo(),500,"El motivo de anulación es obligatorio.");var p=TenantContext.principalActual();var op=idempotencia.begin(p.tenantId(),p.empresaId(),VOID,input.idempotencia(),CommandFingerprint.sha256(input));if(op.replay())return map(seguro(op.resultId()));
  ValeCaja lectura=seguro(input.valeId());SesionCaja sesion=sesiones.bloquear(lectura.getSesionId(),p.tenantId(),p.empresaId()).orElseThrow(()->new RecursoNoEncontradoException("Turno de caja no encontrado."));if(sesion.getStatus()!=EstadoSesionCaja.OPEN)throw new ReglaNegocioException("El vale no puede anularse porque su turno está cerrado.");ValeCaja vale=vales.bloquear(input.valeId(),p.tenantId(),p.empresaId()).orElseThrow(()->new RecursoNoEncontradoException("Vale de caja no encontrado."));if(vale.getEstado()==EstadoValeCaja.VOIDED)throw new ReglaNegocioException("El vale ya fue anulado.");
  MovimientoFinanciero original=movimientos.bloquearMovimientoCaja(vale.getMovimientoId(),p.tenantId(),p.empresaId(),sesion.getId()).orElseThrow(()->new ReglaNegocioException("No se encontró el movimiento financiero del vale."));MovimientoFinanciero reverso=MovimientoFinanciero.reversionCaja(original,sesion.getFechaOperativa(),numerosMovimiento.siguiente(p.tenantId(),p.empresaId()),motivo,p.usuarioId());reverso=movimientos.saveAndFlush(reverso);vale.anular(motivo,p.usuarioId(),p.nombre(),reverso.getId());vale=vales.saveAndFlush(vale);auditoria.registrar("CASH_VOUCHER_VOIDED","ValeCaja",vale.getId(),detalle(vale));idempotencia.complete(p.tenantId(),p.empresaId(),VOID,input.idempotencia(),"CASH_VOUCHER",vale.getId());return map(vale);}

 private SesionCaja sesionPos(UUID id,boolean abierta){var p=TenantContext.principalActual();SesionCaja s=sesiones.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),p.empresaId()).orElseThrow(()->new RecursoNoEncontradoException("Turno de caja no encontrado."));validarSesion(s,abierta);return s;}
 private SesionCaja sesionBloqueada(UUID id){var p=TenantContext.principalActual();SesionCaja s=sesiones.bloquear(id,p.tenantId(),p.empresaId()).orElseThrow(()->new RecursoNoEncontradoException("Turno de caja no encontrado."));validarSesion(s,true);return s;}
 private static void validarSesion(SesionCaja s,boolean abierta){var p=TenantContext.principalActual();if(!EmpresaContext.permiteSucursal(s.getSucursalId())||!p.usuarioId().equals(s.getAbiertoPor()))throw new RecursoNoEncontradoException("Turno de caja no encontrado.");if(abierta&&s.getStatus()!=EstadoSesionCaja.OPEN)throw new ReglaNegocioException("La caja debe estar abierta para confirmar un vale.");}
 private ValeCaja seguro(UUID id){var p=TenantContext.principalActual();ValeCaja v=vales.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),p.empresaId()).orElseThrow(()->new RecursoNoEncontradoException("Vale de caja no encontrado."));if(!EmpresaContext.permiteSucursal(v.getSucursalId()))throw new RecursoNoEncontradoException("Vale de caja no encontrado.");return v;}
 private ConceptoValeCajaDto map(ConceptoValeCaja c){return new ConceptoValeCajaDto(c.getId(),c.getCodigo(),c.getNombre(),c.isRequiereReferencia(),c.isRequiereObservacion());}
 private ValeCajaDto map(ValeCaja v){return new ValeCajaDto(v.getId(),v.getNumero(),v.getFechaHora(),v.getCaja(),v.getSucursal(),v.getMoneda(),v.getUsuario(),v.getConcepto(),v.getBeneficiario(),v.getImporte(),v.getReferencia(),v.getObservacion(),v.getEstado(),v.getSesionId(),v.getMovimientoId(),v.getAnuladoEn(),v.getUsuarioAnulacion(),v.getMotivoAnulacion(),v.getMovimientoReversionId(),v.getEstado()==EstadoValeCaja.CONFIRMED,v.getEmpresaNombre(),v.getEmpresaIdentificacion(),v.getEmpresaDireccion(),v.getEmpresaTelefono(),v.getEmpresaCorreo(),v.getEmpresaLogoObjectKey());}
 private String siguienteVale(UUID tenant,UUID empresa){Long n=jdbc.queryForObject("INSERT INTO cash_voucher_sequence(tenant_id,empresa_id,current_value) VALUES(?,?,1) ON CONFLICT(tenant_id,empresa_id) DO UPDATE SET current_value=cash_voucher_sequence.current_value+1 RETURNING current_value",Long.class,tenant,empresa);return "VAL-"+String.format(Locale.ROOT,"%06d",n);}
 private ZoneId zonaEmpresa(UUID empresa,UUID tenant){String zona=empresas.findByIdAndTenantId(empresa,tenant).map(Empresa::getZonaHoraria).orElse("America/Santo_Domingo");try{return ZoneId.of(zona);}catch(DateTimeException ex){return ZoneId.of("America/Santo_Domingo");}}
 private static String etiqueta(Usuario u){String nombre=(u.getNombre()+" "+u.getApellido()).trim();return nombre.isBlank()?u.getUsuario():u.getUsuario()+" · "+nombre;}
 private static String primero(String a,String b){return a==null||a.isBlank()?b:a.trim();}
 private static UUID valor(UUID id){return id==null?EMPTY_ID:id;}
 private static void validar(ValeCajaInput i){if(i==null||i.sesionId()==null||i.conceptoId()==null||i.idempotencia()==null)throw new ReglaNegocioException("Complete los datos obligatorios del vale.");if(i.importe()==null||i.importe().signum()<=0)throw new ReglaNegocioException("El importe debe ser mayor que cero.");if(i.importe().scale()>4||i.importe().precision()-i.importe().scale()>15)throw new ReglaNegocioException("El importe excede la precisión permitida.");}
 private static void validarPagina(int p,int s,Set<Integer> validos){if(p<0||!validos.contains(s))throw new ReglaNegocioException("Paginación inválida.");}private static BigDecimal escala(BigDecimal x){return x.setScale(4,RoundingMode.HALF_UP);}private static String limpiar(String x){return x==null?"":x.trim();}
 private static String requerido(String x,int max,String mensaje){String v=limpiar(x);if(v.isEmpty())throw new ReglaNegocioException(mensaje);if(v.length()>max)throw new ReglaNegocioException("El valor excede "+max+" caracteres.");return v;}private static String opcional(String x,int max){String v=limpiar(x);if(v.isEmpty())return null;if(v.length()>max)throw new ReglaNegocioException("El valor excede "+max+" caracteres.");return v;}private static String detalle(ValeCaja v){return "{\"numero\":\""+v.getNumero()+"\",\"monto\":"+v.getImporte()+",\"estado\":\""+v.getEstado()+"\"}";}
}
